import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import com.wolinski.shop.platform.ShopProblem;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class OrderService implements OrderFacade {

    private final OrderRepository orders;
    private final CarrierGateway carrier;
    private final TransactionTemplate tx;

    public OrderService(OrderRepository orders, CarrierGateway carrier, PlatformTransactionManager transactions) {
        this.orders = orders;
        this.carrier = carrier;
        this.tx = new TransactionTemplate(transactions);
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    /**
     * Not transactional on purpose (docs/adr/0005): the status change commits first, the carrier is
     * called with no transaction open, and the tracking number is stored in a second transaction.
     * If the carrier fails, the order stays CONFIRMED without a tracking number, and confirming again retries the booking.
     */
    @Override
    public void confirm(String orderId) {
        String alreadyBooked = tx.execute(status -> {
            Order order = orders.get(orderId);
            order.changeStatus("CONFIRMED");
            return order.trackingNumber();
        });
        if (alreadyBooked != null) {
            return;
        }

        String trackingNumber;
        try {
            trackingNumber = carrier.book(orderId);
        } catch (RuntimeException e) {
            throw new ShopProblem("SHIPMENT_NOT_BOOKED",
                    "Order " + orderId + " is confirmed, but the carrier did not book a shipment. Confirm again to retry.", e);
        }

        tx.executeWithoutResult(status -> orders.get(orderId).assignTrackingNumber(trackingNumber));
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status(), order.trackingNumber());
    }
}
}

