import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.InMemoryTransactionManager;
import com.wolinski.shop.platform.ShopProblem;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private final List<String> booked = new ArrayList<>();
    private final List<Boolean> transactionOpenDuringBooking = new ArrayList<>();
    private boolean carrierDown;

    private final CarrierGateway carrier = orderId -> {
        transactionOpenDuringBooking.add(InMemoryTransactionManager.isOpen());
        if (carrierDown) {
            throw new IllegalStateException("carrier timeout");
        }
        booked.add(orderId);
        return "TRK-" + orderId;
    };

    private final OrderService orders = new OrderService(new OrderRepository(), carrier, new InMemoryTransactionManager());

    private String placeOrder() {
        return orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
    }

    @Test
    void confirmBooksAShipmentAndStoresTheTrackingNumber() {
        String id = placeOrder();
        assertNull(orders.summary(id).trackingNumber());

        orders.confirm(id);

        assertEquals("CONFIRMED", orders.summary(id).status());
        assertEquals("TRK-" + id, orders.summary(id).trackingNumber());
        assertEquals(List.of(id), booked);
    }

    @Test
    void theCarrierIsCalledOutsideATransaction() {
        orders.confirm(placeOrder());

        assertEquals(List.of(false), transactionOpenDuringBooking);
    }

    @Test
    void confirmingAgainDoesNotBookASecondShipment() {
        String id = placeOrder();
        orders.confirm(id);
        orders.confirm(id);

        assertEquals(1, booked.size());
    }

    @Test
    void aCarrierFailureLeavesTheOrderConfirmedWithoutTrackingAndConfirmingAgainRetries() {
        String id = placeOrder();
        carrierDown = true;

        ShopProblem problem = assertThrows(ShopProblem.class, () -> orders.confirm(id));
        assertEquals("SHIPMENT_NOT_BOOKED", problem.code());
        assertEquals("CONFIRMED", orders.summary(id).status());
        assertNull(orders.summary(id).trackingNumber());

        carrierDown = false;
        orders.confirm(id);

        assertEquals("TRK-" + id, orders.summary(id).trackingNumber());
        assertEquals(List.of(id), booked);
        assertFalse(transactionOpenDuringBooking.contains(true));
        assertTrue(transactionOpenDuringBooking.size() == 2);
    }
}
}

